// SCENARIO: TEST 03 — Run JS & Read DOM (Screen 2)
import { test } from '@playwright/test';

// How long a step waits for its element, as set in the export.
const TIMEOUT = 10000;
test.use({ actionTimeout: TIMEOUT });

// How the extension finds an element (content.js _locators): each selector in turn
// until one finds it, for up to TIMEOUT; one the page cannot parse is passed over.
async function _find(page, selectors) {
  const end = Date.now() + TIMEOUT;
  for (;;) {
    for (const s of selectors) {
      const el = page.locator(s).first();
      if (await el.count().catch(() => 0)) return el;
    }
    if (Date.now() > end) throw new Error('No element found by ' + selectors.join(' | '));
    await page.waitForTimeout(100);
  }
}

// What Read DOM reads (content.js readElementValue); [from, attr] as one argument.
const _readVal = (el, [from, attr]) => ((el, from, attr) => {
  const tag = String(el.tagName || '').toUpperCase(), fld = tag === 'INPUT' || tag === 'TEXTAREA';
  const txt = () => (typeof el.innerText === 'string' ? el.innerText : (el.textContent || ''));
  const ws = (s) => String(s == null ? '' : s).replace(/\s+/g, ' ').trim();
  if (from === 'attr') return el.getAttribute(attr) ?? '';
  if (from === 'value') {
    if (tag === 'SELECT' && el.multiple) return Array.from(el.selectedOptions).map(o => o.value).join(', ');
    if (fld || tag === 'SELECT') return el.value ?? '';
    if (el.isContentEditable) return txt().trim();
    if (typeof el.value === 'string' && el.value !== '') return el.value;
    if (typeof el.value === 'number' && tag !== 'LI') return String(el.value);
    return txt().trim();
  }
  if (from === 'visible') {
    if (tag === 'SELECT') return Array.from(el.selectedOptions).map(o => ws(o.text)).join(', ');
    if (fld) return el.value ?? '';
    return ws(txt());
  }
  return (el.textContent || '').trim();
})(el, from, attr);

